const items = $input.all();
const out = [];
const nowIso = new Date().toISOString();

for (let i = 0; i < items.length; i++) {
  const raw = items[i].json || {};
  const isWebhook = Boolean(raw.headers || raw.body);
  const isScheduleRow = Boolean(raw.customer_key && raw.account_status && !raw.headers && !raw.body && !raw['Customer Email']);

  if (isScheduleRow && String(raw.account_status).toLowerCase() !== 'active') {
    continue;
  }

  const body = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
  const email = String(body['Customer Email'] ?? body.email ?? body.customer_email ?? body.customer_key ?? '').trim().toLowerCase();
  const name = String(body['Customer Name'] ?? body.name ?? body.customer_name ?? '').trim() || (email ? email.split('@')[0] : 'Customer');
  const company = String(body.Company ?? body.company ?? '').trim() || 'Direct Account';
  const subscriptionPlan = String(body['Subscription Plan'] ?? body.subscription_plan ?? body.plan ?? 'Growth').trim();
  const daysRaw = Number(body['Days Inactive'] ?? body.days_inactive ?? (isScheduleRow ? Number(raw.last_active_days || 0) + 1 : body.last_active_days ?? 0));
  const ticketsRaw = Number(body['Open Support Tickets'] ?? body.open_tickets ?? body.open_tickets_count ?? 0);
  const activitySignal = String(body['Recent Activity Signal'] ?? body.activity_signal ?? body.notes ?? body.event ?? (isScheduleRow ? 'Scheduled daily SaaS health evaluation sweep.' : '')).trim();

  const daysInactive = Number.isNaN(daysRaw) ? 0 : Math.max(0, Math.round(daysRaw));
  const openTickets = Number.isNaN(ticketsRaw) ? 0 : Math.max(0, Math.round(ticketsRaw));
  const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

  out.push({
    json: {
      trigger_source: isScheduleRow ? 'schedule' : (isWebhook ? 'webhook' : 'form'),
      email_valid: emailValid,
      customer_key: email || `invalid-${Date.now()}-${i}`,
      email,
      name,
      company,
      subscription_plan: subscriptionPlan,
      days_inactive: daysInactive,
      open_tickets: openTickets,
      activity_signal: activitySignal || 'Telemetry check',
      evaluated_at: nowIso,
    },
    pairedItem: { item: i },
  });
}

return out;

