parameters.jsCode:
const t = $('Normalize Telemetry Payload').item.json;
const prior = $('Lookup Customer Record').item.json || {};
const raw = $input.item.json || {};
const ai = (raw.output && typeof raw.output === 'object') ? raw.output : raw;

const nowIso = new Date().toISOString();
const entryValidity = String(ai.entry_validity || 'VALID').toUpperCase();
const isSpam = !t.email_valid || entryValidity === 'SPAM' || entryValidity === 'GIBBERISH';

const planMrr = { Starter: 99, Growth: 299, Scale: 699, Enterprise: 1499 };
const subPlan = String(prior.subscription_plan || t.subscription_plan || 'Growth').trim();
const mrrUsd = Number(prior.mrr_usd || planMrr[subPlan] || 299);
const name = String(prior.name || t.name || 'Valued Customer').trim();
const company = String(prior.company || t.company || 'Direct Account').trim();

let hash = 0;
for (let i = 0; i < t.customer_key.length; i++) {
  hash = ((hash << 5) - hash) + t.customer_key.charCodeAt(i);
  hash |= 0;
}
const customerCode = String(prior.customer_code || `CUST-${Math.abs(hash).toString(16).toUpperCase().padStart(6, '0').slice(0, 6)}`);

const parsedScore = Number(ai.risk_score);
let riskScore = Number.isNaN(parsedScore) ? Math.min(95, t.days_inactive * 3 + t.open_tickets * 15) : Math.max(0, Math.min(100, Math.round(parsedScore)));
if (t.days_inactive >= 21 || (t.days_inactive >= 14 && t.open_tickets >= 2)) {
  riskScore = Math.max(riskScore, 80);
} else if (t.days_inactive >= 7 || t.open_tickets >= 1) {
  riskScore = Math.max(riskScore, 50);
}

let riskLevel = String(ai.risk_level || '').toUpperCase();
if (!['HEALTHY', 'AT_RISK', 'URGENT'].includes(riskLevel)) {
  riskLevel = riskScore >= 75 ? 'URGENT' : (riskScore >= 45 ? 'AT_RISK' : 'HEALTHY');
}
if (riskScore >= 75) riskLevel = 'URGENT';
else if (riskScore >= 45 && riskLevel === 'HEALTHY') riskLevel = 'AT_RISK';

const trend = ['IMPROVING', 'STABLE', 'DECLINING'].includes(String(ai.engagement_trend || '').toUpperCase())
  ? String(ai.engagement_trend).toUpperCase()
  : (riskScore >= 50 ? 'DECLINING' : 'STABLE');

const reason = String(ai.reason || `Days inactive: ${t.days_inactive}, open tickets: ${t.open_tickets}.`).trim();
const recommendedAction = String(ai.recommended_action || (riskLevel === 'URGENT' ? 'Immediate executive customer success call.' : (riskLevel === 'AT_RISK' ? 'Send proactive check-in after operator approval.' : 'Continue standard health cadence.'))).trim();

const routeBucket = isSpam ? 'SPAM_REJECTED' : riskLevel;
const escHtml = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const outreachSubject = String(ai.outreach_subject || `Checking in on your ${company} automation workspace — SaaS CRM`).trim();
const outreachBody = String(ai.outreach_body || `We noticed a slight pause in activity across your ${company} workflows and want to make sure everything is running smoothly or help unblock any pending requests.`).trim();

const outreachHtml = `
<div style="font-family:Inter,Segoe UI,Arial,sans-serif;max-width:600px;margin:0 auto;color:#111827;line-height:1.6;">
  <h2 style="color:#0f172a;margin-bottom:8px;">Hi ${escHtml(name)},</h2>
  <p>${escHtml(outreachBody).replace(/\n/g, '<br>')}</p>
  <p style="margin-top:20px;">Best regards,<br><strong>Operator Name</strong><br>SaaS CRM Customer Success</p>
</div>`.trim();

return {
  json: {
    trigger_source: t.trigger_source,
    route_bucket: routeBucket,
    customer_key: t.customer_key,
    customer_code: customerCode,
    name,
    email: t.email,
    company,
    subscription_plan: subPlan,
    mrr_usd: mrrUsd,
    account_status: String(prior.account_status || 'Active'),
    last_active_days: t.days_inactive,
    open_tickets_count: t.open_tickets,
    total_tickets_count: Math.max(Number(prior.total_tickets_count || 0), t.open_tickets),
    current_risk_level: isSpam ? 'HEALTHY' : riskLevel,
    engagement_trend: trend,
    risk_score: riskScore,
    last_reason: reason,
    recommended_action: recommendedAction,
    onboarded_at: prior.onboarded_at || nowIso,
    last_analyzed_at: nowIso,
    updated_at: nowIso,
    outreach_subject: outreachSubject,
    outreach_body: outreachBody,
    outreach_html: outreachHtml,
    event_code: `ENG-${Date.now().toString(36).toUpperCase()}`,
    slack_message: `:rotating_light: *URGENT Churn Risk (${riskScore}/100)*\n*Account:* ${name} — ${company} (${subPlan}, \$${mrrUsd}/mo MRR)\n*Inactive:* ${t.days_inactive}d | *Open Tickets:* ${t.open_tickets}\n*Reason:* ${reason}\n*Action:* ${recommendedAction}`,
    urgent_email_html: `<h2>Urgent SaaS Churn Alert — ${riskScore}/100</h2><p><strong>Customer:</strong> ${escHtml(name)} (${escHtml(company)})</p><p><strong>Plan &amp; MRR:</strong> ${escHtml(subPlan)} (\$${mrrUsd}/mo)</p><p><strong>Days Inactive:</strong> ${t.days_inactive} | <strong>Open Tickets:</strong> ${t.open_tickets}</p><p><strong>Reason:</strong> ${escHtml(reason)}</p><p><strong>Recommended Action:</strong> ${escHtml(recommendedAction)}</p>`,
  },
};

